svg.script:
//
(function() {
  const data = {
    'hs-hippo': {
      title: 'Hipocampo / LTM',
      category: 'Estrutura-Âncora',
      catColor: 'var(--color-focus)',
      catBg: 'var(--color-focus-bg)',
      descLines: [
        'Localizado profundamente na face mesial do lobo',
        'temporal, o hipocampo é o componente central do',
        'sistema límbico, essencial para a consolidação de',
        'memórias de curto prazo e aprendizado espacial.'
      ],
      alertTitle: 'Correlação Fisiopatológica:',
      alertLines: [
        'É a estrutura acometida mais precocemente no',
        'Alzheimer. O acúmulo de proteína Tau causa perda',
        'sináptica e atrofia severa, justificando o déficit',
        'característico de memória para fatos recentes.'
      ],
      alertColor: 'var(--color-red)',
      alertBg: 'var(--color-red-bg)',
      caseText: 'RM: Atrofia hipocampal bilateral (Scheltens 3).'
    },
    'hs-frontal': {
      title: 'Lobo Frontal',
      category: 'Funções Executivas',
      catColor: 'var(--text-title)',
      catBg: 'var(--border-panel)',
      descLines: [
        'Sede das funções executivas superiores, como o',
        'planejamento, tomada de decisões, atenção,',
        'julgamento social, expressão da personalidade e',
        'iniciação de comandos motores voluntários.'
      ],
      alertTitle: 'Comportamento no Alzheimer:',
      alertLines: [
        'Mantém-se estruturalmente íntegro nas fases',
        'iniciais da doença. O acometimento tardio causa',
        'sintomas neuropsiquiátricos como apatia severa,',
        'desinibição, perda de iniciativa e abulia.'
      ],
      alertColor: 'var(--text-muted)',
      alertBg: 'var(--bg-canvas)',
      caseText: 'Clínica: Preservação de comportamento social no início.'
    },
    'hs-occipital': {
      title: 'Lobo Occipital',
      category: 'Processamento Sensorial',
      catColor: 'var(--text-title)',
      catBg: 'var(--border-panel)',
      descLines: [
        'Situado no polo posterior do cérebro, abriga o',
        'córtex visual primário e de associação. É',
        'responsável pelo processamento, interpretação e',
        'reconhecimento de estímulos visuais da retina.'
      ],
      alertTitle: 'Comportamento no Alzheimer:',
      alertLines: [
        'Altamente preservado no Alzheimer típico. A',
        'perda de função visual primária é rara. Se houver',
        'alucinações visuais precoces, deve-se suspeitar',
        'de Demência por Corpos de Lewy ou outras causas.'
      ],
      alertColor: 'var(--color-green)',
      alertBg: 'var(--color-green-bg)',
      caseText: 'Exame: Campos visuais normais; sem agnosias primárias.'
    },
    'hs-cerebellum': {
      title: 'Cerebelo',
      category: 'Coordenação e Equilíbrio',
      catColor: 'var(--color-green)',
      catBg: 'var(--color-green-bg)',
      descLines: [
        'Estrutura posterior responsável pela modulação do',
        'movimento voluntário, coordenação motora fina,',
        'equilíbrio dinâmico, postura e tônus muscular',
        'através de aferências proprioceptivas.'
      ],
      alertTitle: 'Resistência Seletiva:',
      alertLines: [
        'Notoriamente poupado pelo processo degenerativo',
        'do Alzheimer. As vias motoras básicas permanecem',
        'íntegras até as fases terminais da doença, sem',
        'sintomas cerebelares primários.'
      ],
      alertColor: 'var(--color-green)',
      alertBg: 'var(--color-green-bg)',
      caseText: 'Clínica: Marcha independente e reflexos preservados.'
    },
    'hs-caloso': {
      title: 'Corpo Caloso',
      category: 'Conectividade Neural',
      catColor: 'var(--text-title)',
      catBg: 'var(--border-panel)',
      descLines: [
        'Formado por mais de 200 milhões de fibras axônicas',
        'mielinizadas, conecta homologicamente áreas do',
        'córtex dos hemisférios esquerdo e direito, permitindo',
        'a transferência de informações inter-hemisféricas.'
      ],
      alertTitle: 'Degeneração Secundária:',
      alertLines: [
        'Sofre atrofia secundária devido à perda neuronal',
        'difusa no córtex associativo. A perda dessas conexões',
        'resulta na lentificação global do processamento de',
        'informações e declínio cognitivo multidomínio.'
      ],
      alertColor: 'var(--text-muted)',
      alertBg: 'var(--bg-canvas)',
      caseText: 'Cognitivo: Lentificação global na velocidade de processamento.'
    }
  };

  const svg = document.getElementById('bauer-med-svg-p1');
  const panelTitle = svg.querySelector('.panel-body-title');
  const panelCat = svg.querySelector('.panel-status-text');
  const panelCatPill = svg.querySelector('.panel-status-pill');
  const panelClinTitle = svg.querySelector('.panel-clinical-title');
  const panelClinBox = svg.querySelector('.panel-clinical-box');
  const panelCaseValue = svg.querySelector('.panel-case-value');
  const interactiveGroups = svg.querySelectorAll('.clickable-group');
  const fadeElements = svg.querySelectorAll('.fade-transition');

  function updatePanel(id) {
    const info = data[id];
    if (!info) return;

    fadeElements.forEach(el => el.classList.add('fade-out'));

    setTimeout(() => {
      panelTitle.textContent = info.title;
      panelCat.textContent = info.category;
      panelCat.setAttribute('fill', info.catColor);
      panelCatPill.setAttribute('fill', info.catBg);

      const textWidth = panelCat.getComputedTextLength ? panelCat.getComputedTextLength() : 80;
      panelCatPill.setAttribute('width', (textWidth + 16).toString());

      [1, 2, 3, 4].forEach(i => {
        const lineEl = svg.querySelector('.desc-line-' + i);
        if (lineEl) lineEl.textContent = info.descLines[i - 1] || '';
      });

      panelClinTitle.textContent = info.alertTitle;
      panelClinTitle.setAttribute('fill', info.alertColor);
      panelClinBox.setAttribute('fill', info.alertBg);

      [1, 2, 3, 4].forEach(i => {
        const lineEl = svg.querySelector('.alert-line-' + i);
        if (lineEl) lineEl.textContent = info.alertLines[i - 1] || '';
      });

      panelCaseValue.textContent = info.caseText;
      panelCaseValue.setAttribute('fill', info.alertColor);

      fadeElements.forEach(el => el.classList.remove('fade-out'));
    }, 200);
  }

  interactiveGroups.forEach(group => {
    const id = group.getAttribute('id');

    group.addEventListener('click', () => {
      interactiveGroups.forEach(g => g.classList.remove('active'));
      group.classList.add('active');
      updatePanel(id);
    });

    group.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        interactiveGroups.forEach(g => g.classList.remove('active'));
        group.classList.add('active');
        updatePanel(id);
      }
    });
  });

  // Inicialização
  const hippoGroup = document.getElementById('hs-hippo');
  if (hippoGroup) {
    hippoGroup.classList.add('active');
    updatePanel('hs-hippo');
  }
})();
//
